class Solution:
    def checkEquivalence(self, root1: 'Node', root2: 'Node') -> bool:
        # Helper to count variables (iterative to avoid deep recursion)
        def count_vars(root, freq):
            stack = [root]
            while stack:
                node = stack.pop()
                if node.val == '+':
                    stack.append(node.left)
                    stack.append(node.right)
                else:
                    freq[ord(node.val) - ord('a')] += 1
        freq1 = [0] * 26
        freq2 = [0] * 26
        count_vars(root1, freq1)
        count_vars(root2, freq2)
        return freq1 == freq2
